#!/usr/bin/env python3
"""Generate polar boxes from the pinned C++ SMLib, using the output-curve inputs."""
import pathlib
import runpy
import subprocess
import sys

HERE = pathlib.Path(__file__).resolve().parent


def main():
    oracle, raw = sys.argv[1], pathlib.Path(sys.argv[2])
    raw.mkdir(parents=True, exist_ok=True)
    cases = runpy.run_path(str(HERE.parent / 'output-curves' / 'generate.py'))['CASES']
    rows = []
    for op, kind, inputs in cases:
        if op not in ('line', 'hermite'):
            continue
        index = len(rows)
        request = f'{op} {inputs}\n'
        result = subprocess.run(
            ['prlimit', '--as=1073741824', '--cpu=10', 'timeout', '20', oracle],
            input=request, text=True, capture_output=True, check=True)
        (raw / f'{index:04d}.in').write_text(request)
        (raw / f'{index:04d}.out').write_text(result.stdout)
        (raw / f'{index:04d}.err').write_text(result.stderr)
        tokens = result.stdout.split()
        assert tokens.pop(0) == op
        rows.append(f'{op} {kind} | {inputs} | {" ".join(tokens)}')
    (HERE / 'cases.txt').write_text(
        '# Generated by generate.py from the pinned strict SMLib; see README.md.\n'
        + '\n'.join(rows) + '\n')
    print(f'{len(rows)} polar-box cases')


if __name__ == '__main__':
    main()
